import { Injectable } from '@nestjs/common';
import { DataSource, Entity, PrimaryGeneratedColumn, Column } from 'typeorm';

@Entity()
export class Stock {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  productId: string;

  @Column('int')
  quantity: number;
}

@Entity()
export class StockLedger {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  productId: string;

  @Column('int')
  delta: number;

  @Column({ type: 'timestamptz', default: () => 'now()' })
  createdAt: Date;
}

/**
 * Thrown when a decrement request exceeds the remaining stock for a product.
 */
export class OutOfStockException extends Error {
  constructor(productId: string) {
    super(`Product ${productId} is out of stock`);
    this.name = 'OutOfStockException';
  }
}

@Injectable()
export class StockService {
  constructor(private readonly dataSource: DataSource) {}

  /**
   * Decrements the available quantity for a flash-sale product and records
   * the movement in the ledger. Wrapped in a transaction so the guard,
   * the mutation, and the audit write commit or roll back together.
   */
  async decrementStock(productId: string, qty: number): Promise<void> {
    await this.dataSource.transaction(async (manager) => {
      // Read the current stock row for this product.
      const stock = await manager.findOne(Stock, {
        where: { productId },
      });

      if (!stock || stock.quantity < qty) {
        throw new OutOfStockException(productId);
      }

      // Subtract the requested quantity in memory.
      stock.quantity = stock.quantity - qty;

      // Persist the updated quantity.
      await manager.save(stock);

      // Append an audit row for this decrement.
      await manager.save(StockLedger, {
        productId,
        delta: -qty,
      });
    });
  }
}
